                mat[i, j] = True
                queue.append((i, j))
                visited[i, j] = True

    while queue:
        i, j = queue.pop(0)
        for ni, nj in [(i+1,j), (i-1,j), (i,j+1), (i,j-1)]:
            if 0 <= ni < n and 0 <= nj < n:
                if mat[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))

    # Remove any material not connected to chip
    for i in range(n):
