    def erode(mask):
        eroded = np.zeros_like(mask)
        for i in range(1, n-1):
            for j in range(1, n-1):
                if mask[i, j]:
                    if (mask[i-1, j] and mask[i+1, j] and mask[i, j-1] and mask[i, j+1]):
                        eroded[i, j] = True
        return eroded

    def dilate(mask):
        dilated = np.zeros_like(mask)
        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    for di in [-1,0,1]:
