                            if 0 <= ni < n and 0 <= nj < n:
                                dilated[ni, nj] = True
        return dilated

    temp = erode(mat)
    temp = erode(temp)
    mat = dilate(temp)
    mat = dilate(mat)

    # Final pass: ensure chip is still covered
    for i in range(i0, i1+1):
