from collections import deque

def generate(params, n, chip):
    i0, i1, j0, j1 = chip
    trunk_w = int(round(params['trunk_w']))
    branch_levels = int(round(params['branch_levels']))
    split_ratio = float(params['split_ratio'])
    min_w = int(round(params['min_w']))
    max_len_val = int(round(params['max_len']))
    fin_w_taper = float(params['fin_w_taper'])
    fin_pitch = int(round(params['fin_pitch']))
    chip_clearance = int(round(params['chip_clearance']))

    # Ensure minimum widths are at least 2 and odd for symmetry
    trunk_w = max(trunk_w, min_w, 2)
    if trunk_w % 2 == 0:
        trunk_w += 1
    min_w = max(min_w, 2)
    if min_w % 2 == 0:
        min_w += 1

    ci = (i0 + i1) // 2
    cj = (j0 + j1) // 2
    chip_w = i1 - i0 + 1
    chip_h = j1 - j0 + 1

    mat = np.zeros((n, n), dtype=bool)
    mat[i0:i1+1, j0:j1+1] = True  # chip region

    occupied = set()
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            occupied.add((i, j))

    def can_place(x, y, w, h):
        if w <= 0 or h <= 0:
            return False
        x0 = max(0, x - w//2)
        x1 = min(n, x + w//2 + (w % 2))
        y0 = max(0, y - h//2)
        y1 = min(n, y + h//2 + (h % 2))
        if x0 >= x1 or y0 >= y1:
            return False
        for i in range(x0, x1):
            for j in range(y0, y1):
                if not (0 <= i < n and 0 <= j < n):
                    return False
        return True

    def place_rect(x, y, w, h):
        nonlocal occupied
        x0 = max(0, x - w//2)
        x1 = min(n, x + w//2 + (w % 2))
        y0 = max(0, y - h//2)
        y1 = min(n, y + h//2 + (h % 2))
        if x0 >= x1 or y0 >= y1:
            return 0
        added = 0
        for i in range(x0, x1):
            for j in range(y0, y1):
                if not mat[i, j]:
                    mat[i, j] = True
                    occupied.add((i, j))
                    added += 1
        return added

    queue = deque()
    # Start from chip center, grow trunks in 4 directions
    init_dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    for dx, dy in init_dirs:
        length = min(max_len_val, n//2)
        if length < 2:
            continue
        if dx != 0:
            x = ci + dx * length
            y = cj
            w = trunk_w
            h = trunk_w
        else:
            x = ci
            y = cj + dy * length
            w = trunk_w
            h = trunk_w
        if can_place(x, y, w, h):
            added = place_rect(x, y, w, h)
            if added > 0:
                queue.append((x, y, dx, dy, trunk_w, 0, length))  # (x, y, dx, dy, width, level, arm_length)

    # Process queue for hierarchical branching
    while queue and len(occupied) < 1440:
        x, y, dx, dy, width, level, arm_len = queue.popleft()
        if level >= branch_levels:
            continue
        # Two perpendicular directions: rotate 90 deg
        for ndx, ndy in [(-dy, dx), (dy, -dx)]:
            # Branch length decreases with level
            branch_len = max_len_val // (2 ** level)
            if branch_len < 2:
                branch_len = 2
            # Width tapers by split_ratio per level, but not below min_w
            w_next = max(min_w, width // split_ratio)
            # Enforce odd width for symmetry
            if w_next % 2 == 0:
                w_next += 1
            if w_next < min_w:
                w_next = min_w
            # Height is same as width (square cross-section in 2D)
            h_next = w_next
            # Position: start from end of current arm, move outward
            if ndx != 0:
                bx = x + ndx * (arm_len // 2 + branch_len // 2)
                by = y
            else:
                bx = x
                by = y + ndy * (arm_len // 2 + branch_len // 2)
            # Check placement
            if can_place(bx, by, w_next, h_next):
                added = place_rect(bx, by, w_next, h_next)
                if added > 0:
                    # New arm length for next level
                    new_arm_len = branch_len
                    queue.append((bx, by, ndx, ndy, w_next, level+1, new_arm_len))

    # Ensure connectivity: flood fill from chip
    if len(occupied) == 0:
        return mat
    visited = set()
    dq = deque()
    start = next(iter(occupied))
    dq.append(start)
    visited.add(start)
    while dq:
        cx, cy = dq.popleft()
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < n and 0 <= ny < n:
                if mat[nx, ny] and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    dq.append((nx, ny))
    # Remove disconnected material
    for i in range(n):
        for j in range(n):
            if mat[i, j] and (i, j) not in visited:
                mat[i, j] = False

    # Enforce minimum feature size: remove isolated single-cell protrusions
    changed = True
    while changed:
        changed = False
        to_remove = []
        for i in range(n):
            for j in range(n):
                if mat[i, j]:
                    # Count 4-connected neighbors
                    neigh = 0
                    for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+dx, j+dy
                        if 0 <= ni < n and 0 <= nj < n and mat[ni, nj]:
                            neigh += 1
                    if neigh == 0:
                        to_remove.append((i, j))
                    elif neigh == 1:
                        # Check if it's a tip of a feature at least 2 cells long
                        # We'll allow tips, but only if the neighbor has at least 2 neighbors (so feature width >=2)
                        pass  # We rely on placement rules to avoid thin features
        for i, j in to_remove:
            mat[i, j] = False
            changed = True

    # Final check: ensure chip is still present and connected
    chip_region = set()
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            chip_region.add((i, j))
    if not chip_region.issubset(occupied):
        # Re-add chip if removed
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                mat[i, j] = True

    return mat

