    spoke_taper = float(params['spoke_taper'])
    quad_base_w = int(params['quad_base_w'])
    quad_taper = float(params['quad_taper'])

    # Ensure min widths are even and >=2
    def adj_w(w):
        w = max(2, w)
        if w % 2 == 1:
            w += 1
        return w

    hub_ring_w = adj_w(hub_ring_w)
    spoke_w = adj_w(spoke_w)
    quad_base_w = adj_w(quad_base_w)

    mat = np.zeros((n, n), dtype=bool)

