    for i in range(n):
        for j in range(n):
            if (i - ci)**2 + (j - cj)**2 <= hub_r**2:
                mat[i, j] = True

    # Inner rings (radial, within dense_r)
    if dense_r > hub_r:
        n_rings = max(1, (dense_r - hub_r) // 2)
        dr = (dense_r - hub_r) / n_rings
        for k in range(n_rings):
            r_inner = hub_r + k * dr
            r_outer = r_inner + dr
            ring_w = hub_ring_w - quad_taper * k
            ring_w = adj_w(ring_w)
            half_w = ring_w // 2
            for i in range(n):
                for j in range(n):
                    dx = i - ci
                    dy = j - cj
                    dist = math.hypot(dx, dy)
                    if r_inner <= dist <= r_outer:
                        mat[i, j] = True

