    if max_r > dense_r:
        n_spoke_segs = max(1, (max_r - dense_r) // 2)
        ds = (max_r - dense_r) / n_spoke_segs
        for seg in range(n_spoke_segs):
            r_start = dense_r + seg * ds
            r_end = r_start + ds
            r_mid = (r_start + r_end) / 2
            w = spoke_w - spoke_taper * seg
            w = adj_w(w)
            half_w = w // 2
