                s = 0
                while True:
                    r = r_start + s * ds
                    if r > r_end:
                        break
                    i = ci + dx * r
                    j = cj + dy * r
                    if dx != 0:
                        j_min = cj - half_w
                        j_max = cj + half_w
                        for jj in range(j_min, j_max):
                            if 0 <= i < n and 0 <= jj < n:
                                mat[i, jj] = True
                    else:
                        i_min = ci - half_w
                        i_max = ci + half_w
                        for ii in range(i_min, i_max):
                            if 0 <= ii < n and 0 <= j < n:
                                mat[ii, j] = True
                    s += 1

    # Quadtree mesh (orthogonal grid beyond dense_r)
    if max_r > dense_r:
        xs = list(range(0, n, quad_base_w))
        ys = list(range(0, n, quad_base_w))
        # Extend to cover boundary
        if xs[-1] < n:
            xs.append(n)
        if ys[-1] < n:
            ys.append(n)
        for i in range(len(xs)-1):
            for j in range(len(ys)-1):
                x0, x1 = xs[i], xs[i+1]
                y0, y1 = ys[j], ys[j+1]
                xc = (x0 + x1) // 2
                yc = (y0 + y1) // 2
