                        if np.random.rand() < frac:  # But we can't use random — deterministic!
                            pass
        # Instead: deterministic quadtree-like filling by splitting until min size
        # We use a fixed pattern: fill all cells in a grid that are within max_r, but only if they connect to inner region
        # Simpler: fill a orthogonal grid at quad_base_w spacing, but only where it helps connectivity and spread
        # We'll fill lines instead: horizontal and vertical lines at quad_base_w intervals
        step = quad_base_w
