                    mat[i, j] = True
        for j in range(0, n, step):
            if abs(j - cj) <= max_r:
                i_min = max(0, ci - quad_base_w//2)
                i_max = min(n, ci + quad_base_w//2)
                for i in range(i_min, i_max):
                    mat[i, j] = True

    # Ensure chip is covered
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            mat[i, j] = True

