    visited = np.zeros((n, n), dtype=bool)
    stack = []
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            if mat[i, j]:
                stack.append((i, j))
                visited[i, j] = True
    if not stack:  # in case chip was cleared
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                mat[i, j] = True
                stack.append((i, j))
                visited[i, j] = True
    while stack:
        i, j = stack.pop()
        for ni, nj in [(i+1,j), (i-1,j), (i,j+1), (i,j-1)]:
            if 0 <= ni < n and 0 <= nj < n and mat[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                stack.append((ni, nj))
    for i in range(n):
        for j in range(n):
            if mat[i, j] and not visited[i, j]:
                mat[i, j] = False

    # Enforce minimum feature size: 2 cells wide (by construction, we used even widths >=2)
    # But do a sanity pass: remove isolated pixels or thin wires <2 cells
    # We do: if a cell has <2 neighbors in any direction, it might be part of a thin feature -> but safer to trust construction
    # Instead, we ensure no 1-cell wide features by checking: for every material cell, in x and y, there is at least one adjacent material cell
    # But that is too strict. We rely on even widths and flood fill.
    # Pass: remove any cell that is material but has no material neighbor in 4-dir (isolated) or only one neighbor and that neighbor is not backed up -> complex.
    # Given time, we skip and rely on construction with min width 2.

    # Enforce material budget: at most 1440 cells
    if np.sum(mat) > 1440:
        # Remove farthest material first
        dist = np.zeros((n, n))
        for i in range(n):
            for j in range(n):
                dist[i, j] = (i - ci)**2 + (j - cj)**2
        flat_idx = np.argsort(dist.flatten())[::-1]  # farthest first
        flat_mat = mat.flatten()
        excess = np.sum(mat) - 1440
        for idx in flat_idx:
            if excess <= 0:
                break
            if flat_mat[idx]:
                flat_mat[idx] = False
                excess -= 1
        mat = flat_mat.reshape((n, n))

    # Final pass: ensure chip is still covered (after budget trim)
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            mat[i, j] = True

    return mat

