import numpy as np
from collections import deque

def hilbert_curve(order):
    if order == 0:
        return [(0, 0)]
    points = hilbert_curve(order - 1)
    size = 1 << (order - 1)
    new_points = []
    # Bottom-left quadrant
    for x, y in points:
        new_points.append((y, x))
    # Top-left quadrant
    for x, y in points:
        new_points.append((x, y + size))
    # Top-right quadrant
    for x, y in points:
        new_points.append((x + size, y + size))
    # Bottom-right quadrant
    for x, y in points:
        new_points.append((size - 1 - y + size, size - 1 - x))
    return new_points

def generate(params, n, chip):
    order = int(round(float(params['order'])))
