    def width_at(t):
        w_linear = start_w + (end_w - start_w) * t
        # Add slight variation based on turn sharpness (approximated by curvature)
        # For simplicity, use a sinusoidal taper modifier
        turn_effect = turn_taper * 0.5 * (1 - np.cos(2 * np.pi * t))
        return w_linear * (1.0 - turn_effect * 0.2)  # reduce width slightly at turns if turn_taper>0

    # Thicken the curve
    for idx, (x, y) in enumerate(scaled_points):
        t = norm_dists[idx]
        w = width_at(t)
        half_w = max(1, int(round(w / 2)))
        for dx in range(-half_w, half_w + 1):
            for dy in range(-half_w, half_w + 1):
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    grid[nx, ny] = True

    # Ensure chip region is fully covered (it should be by construction, but safeguard)
    for i in range(ci0, ci1 + 1):
        for j in range(cj0, cj1 + 1):
            if 0 <= i < n and 0 <= j < n:
                grid[i, j] = True

    # Enforce minimum feature size of 2 cells by dilation then erosion? 
    # Instead, we rely on width >=2 by construction (end_w >=2, so half_w>=1 -> width>=2)
    # But to be safe, we do a closing operation with 2x2 kernel to ensure no thin spots
    # However, we cannot use scipy, so we do a simple dilation with 2x2 structuring element twice
    # Define 2x2 structuring element
    se = np.array([[1, 1], [1, 1]], dtype=bool)
    # Dilation
    dilated = np.zeros_like(grid)
    for i in range(n):
        for j in range(n):
            if grid[i, j]:
                for di in range(2):
                    for dj in range(2):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < n:
                            dilated[ni, nj] = True
    # Erosion (using dilation of complement, then complement)
    eroded = np.ones_like(grid, dtype=bool)
    for i in range(n):
        for j in range(n):
            all_true = True
            for di in range(2):
                for dj in range(2):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        if not dilated[ni, nj]:
                            all_true = False
                            break
                    else:
                        all_true = False
                        break
                if not all_true:
                    break
            eroded[i, j] = all_true
    grid = eroded

    # Ensure connectivity to chip using BFS from chip
    if not np.any(grid[chip]):
        # If chip not covered (shouldn't happen), seed from chip center
        queue = deque()
        start_i, start_j = chip_center_i, chip_center_j
        if 0 <= start_i < n and 0 <= start_j < n:
            grid[start_i, start_j] = True
            queue.append((start_i, start_j))
        else:
            return grid  # fallback
    else:
        # Start BFS from any chip cell that is material
        queue = deque()
        visited = np.zeros_like(grid, dtype=bool)
        for i in range(ci0, ci1 + 1):
            for j in range(cj0, cj1 + 1):
                if 0 <= i < n and 0 <= j < n and grid[i, j]:
                    queue.append((i, j))
                    visited[i, j] = True
                    break
            if queue:
                break
        if not queue:
            # fallback: seed from chip center
            queue.append((chip_center_i, chip_center_j))
            grid[chip_center_i, chip_center_j] = True
            visited[chip_center_i, chip_center_j] = True

        # BFS to mark connected component
        while queue:
            i, j = queue.popleft()
            for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))
        # Set grid to only the connected component
