    # Enforce material budget: at most 1440 cells
    if np.sum(grid) > 1440:
        # Remove least important cells: farthest from chip
        coords = np.argwhere(grid)
        if len(coords) > 0:
            # Compute distances to chip center
            dists = np.sqrt((coords[:,0] - chip_center_i)**2 + (coords[:,1] - chip_center_j)**2)
            # Sort by distance descending, remove excess
            order = np.argsort(dists)[::-1]  # farthest first
            to_remove = order[np.sum(grid) - 1440:]
            for idx in to_remove:
                i, j = coords[idx]
                grid[i, j] = False
        # After removal, ensure still connected to chip (may break, but we hope not)
        # Re-do connectivity from chip
        if np.any(grid[chip]):
            queue = deque()
            visited = np.zeros_like(grid, dtype=bool)
            for i in range(ci0, ci1 + 1):
                for j in range(cj0, cj1 + 1):
                    if 0 <= i < n and 0 <= j < n and grid[i, j]:
                        queue.append((i, j))
                        visited[i, j] = True
                        break
                if queue:
                    break
            if queue:
                while queue:
                    i, j = queue.popleft()
                    for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                            visited[ni, nj] = True
                            queue.append((ni, nj))
                grid = visited
            else:
                # If disconnected, fill a minimal path to chip
                pass  # hope it doesn't happen

    return grid

