    ring_tip_w = int(max(2, min(3, round(params['ring_tip_w']))))
    max_r = int(max(22, min(28, round(params['max_r']))))

    mat = np.zeros((n, n), dtype=bool)

    # Chip region
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            mat[i, j] = True

    # Hub disc
    for i in range(n):
        for j in range(n):
            if (i - ci) ** 2 + (j - cj) ** 2 <= hub_r ** 2:
                mat[i, j] = True

    # Concentric rings
    if n_rings >= 1:
        dr = (max_r - hub_r) / n_rings
        for k in range(n_rings):
            r_inner = hub_r + k * dr
            r_outer = r_inner + dr
            t = k / (n_rings - 1) if n_rings > 1 else 0.5
            w = ring_base_w + (ring_tip_w - ring_base_w) * t
            w = int(round(max(2, w)))
            if w % 2 == 1:
                w += 1
            half_w = w // 2
            for i in range(n):
                for j in range(n):
                    dx = i - ci
                    dy = j - cj
                    d = math.hypot(dx, dy)
                    if r_inner <= d <= r_outer:
                        mat[i, j] = True

    # Radial fins
    angles = [2 * math.pi * i / n_fins for i in range(n_fins)]
    for theta in angles:
        dx = math.cos(theta)
        dy = math.sin(theta)
        steps = max_r - hub_r
        if steps <= 0:
            continue
        for s in range(int(steps) + 1):
            r = hub_r + s
            t = s / steps if steps > 0 else 0.5
            w = fin_base_w + (fin_tip_w - fin_base_w) * t
            w = int(round(max(2, w)))
            if w % 2 == 1:
                w += 1
            half_w = w // 2
            ix = ci + dx * s
            jy = cj + dy * s
            if abs(dx) > abs(dy):
                j_min = int(round(jy - half_w))
                j_max = int(round(jy + half_w))
                for j in range(j_min, j_max):
                    i = int(round(ix))
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True
            else:
                i_min = int(round(ix - half_w))
                i_max = int(round(ix + half_w))
                for i in range(i_min, i_max):
                    j = int(round(jy))
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True

    # Ensure connectivity via BFS from chip
    visited = np.zeros((n, n), dtype=bool)
    queue = []
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if mat[i, j]:
                visited[i, j] = True
                queue.append((i, j))
    while queue:
        i, j = queue.pop(0)
        for di, dj in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and mat[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                queue.append((ni, nj))
    for i in range(n):
        for j in range(n):
            if mat[i, j] and not visited[i, j]:
                mat[i, j] = False

    # Enforce minimum feature size (2 cells) via erosion/dilation
    def erode(mask):
        m = np.zeros_like(mask)
        for i in range(1, n - 1):
            for j in range(1, n - 1):
                if mask[i, j] and mask[i-1, j] and mask[i+1, j] and mask[i, j-1] and mask[i, j+1]:
                    m[i, j] = True
        return m

    def dilate(mask):
        m = np.zeros_like(mask)
        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    for di in (-1, 0, 1):
                        for dj in (-1, 0, 1):
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < n:
                                m[ni, nj] = True
        return m

    temp = erode(mat)
    temp = erode(temp)
    mat = dilate(temp)
    mat = dilate(temp)

    # Ensure chip remains covered
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            mat[i, j] = True

    # Enforce material budget (<=1440) by removing farthest cells first
    if np.sum(mat) > 1440:
        dist = np.zeros((n, n))
        for i in range(n):
            for j in range(n):
                dist[i, j] = (i - ci) ** 2 + (j - cj) ** 2
        flat_idx = np.argsort(dist.flatten())[::-1]
        flat_mat = mat.flatten()
        excess = np.sum(mat) - 1440
        for idx in flat_idx:
            if excess <= 0:
                break
            if flat_mat[idx]:
                flat_mat[idx] = False
                excess -= 1
        mat = flat_mat.reshape((n, n))

    return mat

import numpy as np
import math

def generate(params, n, chip):
    i0, i1, j0, j1 = chip
    ci = (i0 + i1) // 2
    cj = (j0 + j1) // 2

    hub_r = int(round(float(params['hub_r'])))
    trans_r = int(round(float(params['trans_r'])))
    max_r = int(round(float(params['max_r'])))
    n_spokes = int(round(float(params['n_spokes'])))
    spoke_w = int(round(float(params['spoke_w'])))
    grid_pitch = int(round(float(params['grid_pitch'])))
    grid_w = int(round(float(params['grid_w'])))
    diag_w = int(round(float(params['diag_w'])))

    # Clamp parameters to satisfy constraints
    hub_r = max(0, min(hub_r, n//2))
    trans_r = max(hub_r + 2, min(trans_r, n//2))
    max_r = max(trans_r + 2, min(max_r, n//2))
    n_spokes = max(4, min(n_spokes, 32))
    spoke_w = max(2, min(spoke_w, 6))
    if spoke_w % 2 == 1:
        spoke_w += 1
    grid_pitch = max(2, min(grid_pitch, 10))
    grid_w = max(2, min(grid_w, 4))
    if grid_w % 2 == 1:
        grid_w += 1
    diag_w = max(2, min(diag_w, 4))
    if diag_w % 2 == 1:
        diag_w += 1

    mat = np.zeros((n, n), dtype=bool)

    # Chip region: always material
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            mat[i, j] = True

    # Hub: filled circle up to hub_r
    for i in range(n):
        for j in range(n):
            if (i - ci)**2 + (j - cj)**2 <= hub_r**2:
                mat[i, j] = True

    # Spokes: from hub_r to trans_r, n_spokes directions
    angles = [2 * math.pi * k / n_spokes for k in range(n_spokes)]
    for angle in angles:
        dx = math.cos(angle)
        dy = math.sin(angle)
        steps = trans_r - hub_r
        if steps <= 0:
            continue
        for s in range(steps + 1):
            r = hub_r + s
            if r > trans_r:
                break
            i_center = ci + round(dx * r)
            j_center = cj + round(dy * r)
            half_w = spoke_w // 2
            if abs(dx) >= abs(dy):  # horizontal dominant
                i = i_center
                j_min = j_center - half_w
                j_max = j_center + half_w
                for j in range(j_min, j_max):
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True
            else:  # vertical dominant
                j = j_center
                i_min = i_center - half_w
                i_max = i_center + half_w
                for i in range(i_min, i_max):
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True

    # Diagonal fins: 45-degree lines from trans_r to max_r, bridging to grid
    diag_angles = [math.pi/4, 3*math.pi/4, 5*math.pi/4, 7*math.pi/4]
    for angle in diag_angles:
        dx = math.cos(angle)
        dy = math.sin(angle)
        steps = max_r - trans_r
        if steps <= 0:
            continue
        for s in range(steps + 1):
            r = trans_r + s
            if r > max_r:
                break
            i_center = ci + round(dx * r)
            j_center = cj + round(dy * r)
            half_w = diag_w // 2
            if abs(dx) >= abs(dy):  # horizontal dominant
                i = i_center
                j_min = j_center - half_w
                j_max = j_center + half_w
                for j in range(j_min, j_max):
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True
            else:  # vertical dominant
                j = j_center
                i_min = i_center - half_w
                i_max = i_center + half_w
                for i in range(i_min, i_max):
                    if 0 <= i < n and 0 <= j < n:
                        mat[i, j] = True

    # Cartesian grid: from max_r inward, aligned to grid_pitch
    # We fill a square grid pattern from the outer boundary inward
    start_i = ci - max_r
    end_i = ci + max_r
    start_j = cj - max_r
    end_j = cj + max_r
    # Align to grid_pitch
    si = start_i + ((-start_i) % grid_pitch)
    sj = start_j + ((-start_j) % grid_pitch)
    for i in range(si, end_i + 1, grid_pitch):
        for j in range(sj, end_j + 1, grid_pitch):
            if 0 <= i < n and 0 <= j < n:
                # Horizontal bar
                ii_min = max(0, i - grid_w//2)
                ii_max = min(n, i + grid_w//2 + 1)
                for ii in range(ii_min, ii_max):
                    mat[ii, j] = True
                # Vertical bar
                jj_min = max(0, j - grid_w//2)
                jj_max = min(n, j + grid_w//2 + 1)
                for jj in range(jj_min, jj_max):
                    mat[i, jj] = True

    # Enforce connectivity: ensure all material is 4-connected to chip
    visited = np.zeros((n, n), dtype=bool)
    queue = []
    chip_filled = False
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            if mat[i, j]:
                queue.append((i, j))
                visited[i, j] = True
                chip_filled = True
    if not chip_filled:
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                mat[i, j] = True
                queue.append((i, j))
                visited[i, j] = True

    while queue:
        i, j = queue.pop(0)
        for ni, nj in [(i+1,j), (i-1,j), (i,j+1), (i,j-1)]:
            if 0 <= ni < n and 0 <= nj < n:
                if mat[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))

    # Remove any material not connected to chip
    for i in range(n):
        for j in range(n):
            if mat[i, j] and not visited[i, j]:
                mat[i, j] = False

    # Enforce minimum feature size: 2 cells wide via erosion/dilation
    def erode(mask):
        eroded = np.zeros_like(mask)
        for i in range(1, n-1):
            for j in range(1, n-1):
                if mask[i, j]:
                    if (mask[i-1, j] and mask[i+1, j] and mask[i, j-1] and mask[i, j+1]):
                        eroded[i, j] = True
        return eroded

    def dilate(mask):
        dilated = np.zeros_like(mask)
        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    for di in [-1,0,1]:
                        for dj in [-1,0,1]:
                            ni, nj = i+di, j+dj
                            if 0 <= ni < n and 0 <= nj < n:
                                dilated[ni, nj] = True
        return dilated

    temp = erode(mat)
    temp = erode(temp)
    mat = dilate(temp)
    mat = dilate(mat)

    # Final pass: ensure chip is still covered
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            mat[i, j] = True

    # Enforce material budget: at most 1440 cells
    if np.sum(mat) > 1440:
        flat_idx = np.argsort(((np.arange(n)[:,None]-ci)**2 + (np.arange(n)[None,:]-cj)**2).flatten())[::-1]
        flat_mat = mat.flatten()
        excess = np.sum(mat) - 1440
        for idx in flat_idx:
            if excess <= 0:
                break
            if flat_mat[idx]:
                flat_mat[idx] = False
                excess -= 1
        mat = flat_mat.reshape((n, n))

    return mat

import numpy as np
import math

def generate(params, n, chip):
    i0, i1, j0, j1 = chip
    ci = (i0 + i1) // 2
    cj = (j0 + j1) // 2

    n_arms = int(round(params['n_arms']))
    start_r = int(round(params['start_r']))
    max_r = int(round(params['max_r']))
    center_w = int(round(params['center_w']))
    edge_w = int(round(params['edge_w']))
    turns = int(round(params['turns']))
    branch_r = int(round(params['branch_r']))
    branch_angle_deg = int(round(params['branch_angle']))

    # Parameter enforcement
    n_arms = max(4, min(8, n_arms))
    start_r = max(3, min(6, start_r))
    max_r = max(24, min(28, max_r))
    if max_r <= start_r:
        max_r = start_r + 4
    center_w = max(5, min(8, center_w))
    if center_w % 2 == 1:
        center_w += 1
    edge_w = max(2, min(3, edge_w))
    if edge_w % 2 == 1:
        edge_w += 1
    turns = max(3, min(5, turns))
    branch_r = max(10, min(16, branch_r))
    branch_angle_deg = max(30, min(60, branch_angle_deg))

    mat = np.zeros((n, n), dtype=bool)

    # Chip must be material
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                mat[i, j] = True

    angle_per_arm = 2 * math.pi / n_arms
    branch_angle = math.radians(branch_angle_deg)

    for arm in range(n_arms):
        arm_start_angle = arm * angle_per_arm
        r = start_r
        theta = 0.0
        dtheta = 0.05  # radian step for smooth spiral
        total_theta = turns * 2 * math.pi

        while theta <= total_theta and r <= max_r:
            # Width interpolation: linear from center_w at r=0 to edge_w at r=max_r
            width = center_w + (edge_w - center_w) * (r / max_r)
            width = int(round(width))
            if width < 2:
                width = 2
            if width % 2 == 1:
                width += 1
            half_w = width // 2

            # Main spiral point
            x_main = ci + r * math.cos(arm_start_angle + theta)
            y_main = cj + r * math.sin(arm_start_angle + theta)

            # Tangent direction (perpendicular to radial)
            tx = -math.sin(arm_start_angle + theta)
            ty = math.cos(arm_start_angle + theta)

            # Mark main arm
            for i in range(n):
                for j in range(n):
                    dx = i - x_main
                    dy = j - y_main
                    dist_to_line = abs(dx * tx + dy * ty)
                    if dist_to_line <= half_w:
                        if 0 <= i < n and 0 <= j < n:
                            mat[i, j] = True

            # Branch: if beyond branch_r, add a side arm
            if r >= branch_r:
                branch_length = min(r - branch_r, 8)  # limit branch length
                if branch_length > 0:
                    for b in range(1, branch_length + 1):
                        rb = r + b * 0.5  # branch extends outward
                        if rb > max_r:
                            break
                        xb = ci + rb * math.cos(arm_start_angle + theta + branch_angle)
                        yb = cj + rb * math.sin(arm_start_angle + theta + branch_angle)
                        wb = edge_w  # use edge width for branch
                        half_wb = wb // 2
                        txb = -math.sin(arm_start_angle + theta + branch_angle)
                        tyb = math.cos(arm_start_angle + theta + branch_angle)
                        for i in range(n):
                            for j in range(n):
                                dx = i - xb
                                dy = j - yb
                                dist_to_line = abs(dx * txb + dy * tyb)
                                if dist_to_line <= half_wb:
                                    if 0 <= i < n and 0 <= j < n:
                                        mat[i, j] = True

            # Advance spiral
            # Pitch: distance per radian, set so that after total_theta, r ~ max_r
            pitch = max_r / total_theta if total_theta > 0 else 0
            r += pitch * dtheta
            theta += dtheta

    # Ensure connectivity from chip via flood-fill (4-connected)
    visited = np.zeros((n, n), dtype=bool)
    stack = []
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                stack.append((i, j))
                visited[i, j] = True

    while stack:
        i, j = stack.pop()
        for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                if mat[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    stack.append((ni, nj))

    # Remove disconnected material
    for i in range(n):
        for j in range(n):
            if mat[i, j] and not visited[i, j]:
                mat[i, j] = False

    # Enforce minimum feature size (>=2 cells) using two rounds of erosion then dilation
    def erode(mask):
        eroded = np.zeros_like(mask)
        for i in range(1, n-1):
            for j in range(1, n-1):
                if mask[i, j]:
                    if (mask[i-1, j] and mask[i+1, j] and mask[i, j-1] and mask[i, j+1]):
                        eroded[i, j] = True
        return eroded

    def dilate(mask):
        dilated = np.zeros_like(mask)
        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    for di in (-1, 0, 1):
