        flat_idx = np.argsort(dist_from_center, axis=None)[::-1]  # farthest first
        flat_mat = mat.flatten()
        excess = np.sum(mat) - 1440
        for idx in flat_idx:
            if excess <= 0:
                break
            if flat_mat[idx]:
                flat_mat[idx] = False
                excess -= 1
        mat = flat_mat.reshape((n, n))

    return mat

import numpy as np
import math

def generate(params, n, chip):
    i0, i1, j0, j1 = chip
    ci = (i0 + i1) // 2
    cj = (j0 + j1) // 2

    start_r = int(round(params['start_r']))
    max_r = int(round(params['max_r']))
    center_w = int(round(params['center_w']))
    edge_w = int(round(params['edge_w']))
    turns = int(round(params['turns']))
    branch_r = int(round(params['branch_r']))
    branch_angle_deg = int(round(params['branch_angle']))

    # Enforce constraints
    start_r = max(start_r, 1)
    max_r = max(max_r, start_r + 1)
    center_w = max(center_w, 2)
    edge_w = max(edge_w, 2)
    turns = max(turns, 1)
    branch_r = max(branch_r, start_r + 1)
    branch_angle_deg = max(branch_angle_deg, 1)
    n_arms = max(int(round(params['n_arms'])), 2)

    # Ensure even widths for symmetry
    if center_w % 2 == 1:
        center_w += 1
    if edge_w % 2 == 1:
        edge_w += 1

    mat = np.zeros((n, n), dtype=bool)

    # Fill chip area
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                mat[i, j] = True

    # Generate branched spiral arms
    arm_angle_step = 2 * math.pi / n_arms
    total_angle = turns * 2 * math.pi
    theta_step = 0.05  # radians per step for smooth curve

    for arm in range(n_arms):
        base_angle = arm * arm_angle_step
        r = start_r
        theta = 0.0
        while theta <= total_angle and r <= max_r:
            # Determine if branching occurs at this radius
            if r >= branch_r:
                # Calculate branch angle in radians
                branch_angle = math.radians(branch_angle_deg)
                # Two branches: +/- branch_angle from main arm
                for sign in [-1, 1]:
                    branch_theta = theta + sign * branch_angle
                    branch_r = r
                    # Draw branch inward slightly
                    branch_length = min(r * 0.3, 5.0)  # limit branch length
                    bl = 0.0
                    while bl < branch_length and branch_r >= start_r:
                        # Width tapers linearly from center_w to edge_w
                        prog = (branch_r - start_r) / (max_r - start_r) if max_r > start_r else 0.5
                        width = int(round(center_w + (edge_w - center_w) * prog))
                        width = max(2, width if width % 2 == 0 else width + 1)
                        half_w = width // 2
                        # Local tangent for branch
                        tx = -math.sin(branch_theta)
                        ty = math.cos(branch_theta)
                        x = ci + branch_r * math.cos(branch_theta)
                        y = cj + branch_r * math.sin(branch_theta)
                        # Mark cells near branch line
                        for i in range(n):
                            for j in range(n):
                                dx = i - x
                                dy = j - y
                                dist_to_line = abs(dx * tx + dy * ty)
                                if dist_to_line <= half_w:
                                    if 0 <= i < n and 0 <= j < n:
                                        mat[i, j] = True
                        # Step along branch
